# examples/quality_compare.py › def models_for(tree_dir: Path) -> ModelBundle
# uses: from pathlib import Path; from raptor.models import ModelBundle, open_cache, with_cache; from raptor.models.gemini import GeminiEmbeddingModel, GeminiQAModel, GeminiSummarizationModel; from raptor.settings import get_settings
def models_for(tree_dir: Path) -> ModelBundle:
    legacy = (
        tree_dir.exists()
        and "doc=None" in (tree_dir / "tree.json").read_text(encoding="utf-8")[:4000]
    )
    # Converted demo trees were embedded without task types; query them the same way.
    task = {} if not legacy else {"document_task_type": None, "query_task_type": None}
    bundle = ModelBundle(GeminiEmbeddingModel(**task), GeminiSummarizationModel(), GeminiQAModel())
    return with_cache(bundle, open_cache(get_settings().cache_dir))

# examples/quality_compare.py › module-level code
if __name__ == "__main__":
    main()

# raptor/__init__.py › def __getattr__(name: str) -> Any
# uses: from typing import Any
def __getattr__(name: str) -> Any:
    if name in _LAZY:
        import importlib

        module, attr = _LAZY[name]
        return getattr(importlib.import_module(module), attr)
    raise AttributeError(f"module 'raptor' has no attribute {name!r}")

# raptor/builder.py › class TreeBuilder › def build_from_text(self, text: str, *, progress: ProgressCallback | None = None) -> Tree
# uses: from .types import Node, Tree, nodes_text
    def build_from_text(self, text: str, *, progress: ProgressCallback | None = None) -> Tree:
        progress = progress or _noop
        progress({"stage": "chunking"})
        chunks = self.chunker.split(text)
        if not chunks:
            raise ValueError("document produced no chunks (is it empty?)")
        return self.build_from_chunks(chunks, progress=progress)

# raptor/chunking/__init__.py › def make_chunker(cfg: ChunkingConfig, embedding_model: BaseEmbeddingModel | None = None) -> Chunker
# uses: from ..config import ChunkingConfig; from .base import CHUNKERS, Chunk, Chunker, default_tokenizer; from ..models.base import BaseEmbeddingModel
def make_chunker(cfg: ChunkingConfig, embedding_model: BaseEmbeddingModel | None = None) -> Chunker:
    """Build the configured chunker. ``embedding_model`` is used by embedding-aware strategies."""
    extra = {"embedding_model": embedding_model} if embedding_model is not None else {}
    return CHUNKERS.create(
        cfg.strategy,
        max_tokens=cfg.max_tokens,
        overlap_tokens=cfg.overlap_tokens,
        **extra,
        **cfg.params,
    )

# raptor/chunking/base.py › class Chunker › Chunker, Chunker.split, Chunker.split_texts
# uses: from abc import ABC, abstractmethod
class Chunker(ABC):

    @abstractmethod
    def split(self, text: str) -> list[Chunk]: ...

    def split_texts(self, text: str) -> list[str]:
        return [c.text for c in self.split(text)]

metadata.docstring:
Sentence-greedy chunking (the original RAPTOR strategy, with bugs fixed).

Sentences are packed into chunks of at most ``max_tokens`` tokens. Fixes over the
original ``split_text``:

* sentence-ending punctuation is kept (the old regex split *on* ``.!?`` and dropped them);
* chunk text is the exact source slice, so offsets are reliable;
* ``overlap_tokens`` really is a token budget (old code mixed chunk-local and global
  indices when computing the carried-over length);
* sentences longer than ``max_tokens`` are split on clause punctuation and then, if
  still too long, by token windows, so no chunk exceeds the limit.

