    def files(self) -> list[str]:
        return sorted(self._files)

    def node_hit(self, node_index: int, score: float = 0.0) -> CodeHit:
        return to_hit(self.tree.all_nodes[node_index], score)

# raptor/code/index.py › class CodeIndex › def _call_neighbors(self, node_index: int) -> tuple[list[int], list[int]]
# uses: from .search import CodeSearcher, node_kind, to_hit
    def _call_neighbors(self, node_index: int) -> tuple[list[int], list[int]]:
        node = self.tree.all_nodes[node_index]
        kind = node_kind(node)
        s = self.searcher
        if kind == "file":
            imports_out = [e.dst for e in self.edges if e.kind == "imports" and e.src == node_index]
            imports_in = [e.src for e in self.edges if e.kind == "imports" and e.dst == node_index]
            return imports_in, imports_out
        members = {node_index}
        if kind == "class":
            members |= set(node.children)
        callers = [c for m in members for c in s.callers.get(m, []) if c not in members]
        callees = [c for m in members for c in s.callees.get(m, []) if c not in members]
        return list(dict.fromkeys(callers)), list(dict.fromkeys(callees))

# raptor/code/index.py › class CodeIndex › def module_node(self, path: str) -> int | None
    def module_node(self, path: str) -> int | None:
        """Node index of the file or directory ``path`` (or the repo for ``.``/empty)."""
        path = path.strip().strip("/").replace("\\", "/")
        for n in self.tree.all_nodes.values():
            m = n.metadata
            if path in ("", ".") and m.get("kind") == "repo":
                return n.index
            if m.get("kind") in ("file", "dir") and m.get("path") == path:
                return n.index
        # Accept a dotted module name, e.g. "raptor.code.index".
        dotted = path.replace(".", "/")
        for cand in (f"{dotted}.py", f"{dotted}/__init__.py", dotted):
            for n in self.tree.all_nodes.values():
                m = n.metadata
                if m.get("kind") in ("file", "dir") and (
                    m.get("path") == cand or str(m.get("path", "")).endswith("/" + cand)
                ):
                    return n.index
        return None

# raptor/code/index.py › class CodeIndex › def outline(self, max_depth: int = 4) -> list[tuple[int, CodeHit]]
# uses: from .types import CodeAnswer, CodeEdge, CodeHit
    def outline(self, max_depth: int = 4) -> list[tuple[int, CodeHit]]:
        """``(depth, hit)`` rows of the structural hierarchy, repo first (for printing)."""
        repo = next(n for n in self.tree.root_nodes.values() if n.metadata.get("kind") == "repo")
        rows: list[tuple[int, CodeHit]] = []

        def visit(idx: int, depth: int) -> None:
            node = self.tree.all_nodes[idx]
            rows.append((depth, self.node_hit(idx)))
            if depth >= max_depth:
                return
            kids = sorted(
                node.children,
                key=lambda c: (
                    self.tree.all_nodes[c].metadata.get("kind") != "dir",
                    str(self.tree.all_nodes[c].metadata.get("path", "")),
                    self.tree.all_nodes[c].metadata.get("start_line", 0),
                ),
            )
            for c in kids:
                visit(c, depth + 1)

        visit(repo.index, 0)
        for n in sorted(self.tree.root_nodes.values(), key=lambda n: n.index):
            if n.metadata.get("kind") == "concept":
                rows.append((0, self.node_hit(n.index)))
        return rows

# raptor/code/index.py › class CodeIndex › def stats(self) -> dict[str, Any]
# uses: from typing import Any; from .search import CodeSearcher, node_kind, to_hit
    def stats(self) -> dict[str, Any]:
        counts: dict[str, int] = {}
        for n in self.tree.all_nodes.values():
            k = node_kind(n)
            counts[k] = counts.get(k, 0) + 1
        edges: dict[str, int] = {}
        for e in self.edges:
            edges[e.kind] = edges.get(e.kind, 0) + 1
        return {
            "repo_path": str(self.repo_path),
            "files": len(self._files),
            "nodes": counts,
            "edges": edges,
            "layers": self.tree.num_layers + 1,
            "git_commit": self.git_commit,
        }

# raptor/code/ingest.py › sha256_bytes, is_binary
# uses: import hashlib
def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def is_binary(data: bytes) -> bool:
    return b"\x00" in data[:8192]

# raptor/code/ingest.py › def is_generated(path: str, data: bytes) -> bool
def is_generated(path: str, data: bytes) -> bool:
    if path.endswith(GENERATED_SUFFIXES):
        return True
    head = data[:600].decode("utf-8", errors="ignore").lower()
    return any(m in head for m in GENERATED_MARKERS)

# raptor/code/ingest.py › def _skip_by_dir(rel: str) -> bool
def _skip_by_dir(rel: str) -> bool:
    parts = rel.split("/")[:-1]
    return any(p in SKIP_DIRS or p.endswith(".egg-info") for p in parts)

# raptor/code/ingest.py › def _pathspec(patterns: Iterable[str])
# uses: from collections.abc import Iterable
def _pathspec(patterns: Iterable[str]):
    import pathspec

    try:  # pathspec >= 0.12.2 names the git-compatible flavour "gitignore"
        return pathspec.PathSpec.from_lines("gitignore", list(patterns))
    except (KeyError, LookupError):
        return pathspec.PathSpec.from_lines("gitwildmatch", list(patterns))

# raptor/code/ingest.py › def _git_files(root: Path) -> list[str] | None
# uses: import shutil; import subprocess; from pathlib import Path
def _git_files(root: Path) -> list[str] | None:
    git = shutil.which("git")
    if git is None or not (root / ".git").exists():
        return None
    try:
        out = subprocess.run(
            [git, "-C", str(root), "ls-files", "-z", "--cached", "--others", "--exclude-standard"],
            capture_output=True,
            check=True,
            timeout=60,
        ).stdout
    except (subprocess.SubprocessError, OSError) as exc:
        logger.warning("git ls-files failed (%s); falling back to walking the tree", exc)
        return None
    return sorted({p for p in out.decode("utf-8", errors="replace").split("\0") if p})

# raptor/code/ingest.py › def _walk_files(root: Path) -> list[str]
# uses: import os; from pathlib import Path
def _walk_files(root: Path) -> list[str]:
    """Walk ``root`` honouring every ``.gitignore`` found on the way down."""
    specs: list[tuple[str, object]] = []
    out: list[str] = []
    for dirpath, dirnames, filenames in os.walk(root):
        rel_dir = Path(dirpath).relative_to(root).as_posix()
        rel_dir = "" if rel_dir == "." else rel_dir
        if ".gitignore" in filenames:
            lines = (Path(dirpath) / ".gitignore").read_text(encoding="utf-8", errors="ignore")
            specs.append((rel_dir, _pathspec(lines.splitlines())))

        def ignored(rel: str, is_dir: bool) -> bool:
            for base, spec in specs:
                if base and not rel.startswith(base + "/"):
                    continue
                sub = rel[len(base) + 1 :] if base else rel
                if spec.match_file(sub + ("/" if is_dir else "")):  # type: ignore[attr-defined]
                    return True
            return False

        keep = []
        for d in sorted(dirnames):
            rel = f"{rel_dir}/{d}" if rel_dir else d
            if d in SKIP_DIRS or d.endswith(".egg-info") or ignored(rel, True):
                continue
            keep.append(d)
        dirnames[:] = keep
        for f in sorted(filenames):
            rel = f"{rel_dir}/{f}" if rel_dir else f
            if not ignored(rel, False):
                out.append(rel)
    return sorted(out)

# raptor/code/ingest.py › def read_source(root: str | Path, rel: str, cfg: IngestConfig) -> bytes | None
# uses: from pathlib import Path; from .config import IngestConfig
def read_source(root: str | Path, rel: str, cfg: IngestConfig) -> bytes | None:
    """File contents, or ``None`` if the file is missing, too big, binary or generated."""
    path = Path(root) / rel
    try:
        if path.stat().st_size > cfg.max_file_bytes:
            logger.info("skipping %s: larger than %d bytes", rel, cfg.max_file_bytes)
            return None
        data = path.read_bytes()
    except OSError:
        return None
    if is_binary(data) or is_generated(rel, data):
        return None
    return data

# raptor/code/ingest.py › def git_head(root: str | Path) -> str | None
# uses: import shutil; import subprocess; from pathlib import Path
def git_head(root: str | Path) -> str | None:
    git = shutil.which("git")
    if git is None or not (Path(root) / ".git").exists():
        return None
    try:
        out = subprocess.run(
            [git, "-C", str(root), "rev-parse", "HEAD"], capture_output=True, check=True, timeout=30
        ).stdout
    except (subprocess.SubprocessError, OSError):
        return None
    return out.decode().strip() or None

# raptor/code/languages/__init__.py › def make_extractors(languages: list[str]) -> dict[str, LanguageExtractor]
# uses: from .base import EXTRACTORS, ImportRef, LanguageExtractor, ParsedFile, Symbol
def make_extractors(languages: list[str]) -> dict[str, LanguageExtractor]:
    """Instantiate the extractors for ``languages``; returns ``{extension: extractor}``."""
    out: dict[str, LanguageExtractor] = {}
    for name in languages:
        ex = EXTRACTORS.create(name)
        for ext in ex.extensions:
            out[ext] = ex
    return out

# raptor/code/languages/__init__.py › def extractor_for(path: str, extractors: dict[str, LanguageExtractor]) -> LanguageExtractor | None
# uses: from .base import EXTRACTORS, ImportRef, LanguageExtractor, ParsedFile, Symbol
def extractor_for(path: str, extractors: dict[str, LanguageExtractor]) -> LanguageExtractor | None:
    lower = path.lower()
    for ext, ex in extractors.items():
        if lower.endswith(ext):
            return ex
    return None

