def _verdict(cmp: dict[str, Any] | None) -> str:
    if cmp is None:
        return "baseline"
    if cmp["mcnemar_p"] < ALPHA:
        return "**better**" if cmp["delta"] > 0 else "**worse**"
    return "within noise"

# raptor/eval/report.py › def _pct(x: float | None, digits: int = 1) -> str
