# uses: from datetime import datetime, timezone
def _now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")

# raptor/eval/runs.py › def list_runs(root: str | Path = DEFAULT_RUNS_DIR) -> list[dict[str, Any]]
# uses: import json; from pathlib import Path; from typing import Any; from .runner import DEFAULT_RUNS_DIR, read_jsonl
def list_runs(root: str | Path = DEFAULT_RUNS_DIR) -> list[dict[str, Any]]:
    """Summaries of every finished run, oldest first."""
    root = Path(root)
    if not root.exists():
        return []
    out = []
    for f in sorted(root.glob("*/summary.json")):
        try:
            out.append(json.loads(f.read_text(encoding="utf-8")))
        except json.JSONDecodeError:
            continue
    return sorted(out, key=lambda s: (s.get("created_at", ""), s.get("run_id", "")))

# raptor/eval/runs.py › def load_run(run_id: str, root: str | Path = DEFAULT_RUNS_DIR) -> tuple[dict[str, Any], list[dict[str, Any]]]
# uses: import json; from pathlib import Path; from typing import Any; from .runner import DEFAULT_RUNS_DIR, read_jsonl
def load_run(
    run_id: str, root: str | Path = DEFAULT_RUNS_DIR
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    """``(summary, results rows)`` for one run."""
    run_dir = Path(root) / run_id
    summary_file = run_dir / "summary.json"
    if not summary_file.exists():
        raise FileNotFoundError(f"no finished run {run_id!r} in {root}")
    return json.loads(summary_file.read_text(encoding="utf-8")), read_jsonl(
        run_dir / "results.jsonl"
    )

# raptor/eval/runs.py › def find_run(name_or_id: str, root: str | Path = DEFAULT_RUNS_DIR) -> dict[str, Any]
# uses: from pathlib import Path; from typing import Any; from .runner import DEFAULT_RUNS_DIR, read_jsonl
def find_run(name_or_id: str, root: str | Path = DEFAULT_RUNS_DIR) -> dict[str, Any]:
    """Look a run up by id, or by experiment name (the latest run with that name)."""
    runs = list_runs(root)
    for s in runs:
        if s["run_id"] == name_or_id:
            return s
    named = [s for s in runs if s.get("name") == name_or_id]
    if not named:
        raise KeyError(f"no run with id or name {name_or_id!r}")
    return named[-1]

# raptor/eval/splits.py › def make_splits(articles: list[QualityArticle], *, seed: int = DEFAULT_SEED, size: int = DEFAULT_SIZE, source: str = "dev",) -> dict[str, SplitSpec]
# uses: import random; from .datasets.quality import DEFAULT_DIR, QualityArticle, load_quality
def make_splits(
    articles: list[QualityArticle],
    *,
    seed: int = DEFAULT_SEED,
    size: int = DEFAULT_SIZE,
    source: str = "dev",
) -> dict[str, SplitSpec]:
    """Pick ``size`` sets for ``dev`` and ``size`` for ``confirm``, from disjoint articles.

    Only sets with gold labels are eligible. One set is taken per article.
    """
    by_article: dict[str, list[QualityArticle]] = {}
    for art in articles:
        if art.questions and all(q.gold_label is not None for q in art.questions):
            by_article.setdefault(art.article_id, []).append(art)
    article_ids = sorted(by_article)
    if len(article_ids) < 2 * size:
        raise ValueError(f"need {2 * size} articles, found {len(article_ids)}")
    rng = random.Random(seed)
    picked = rng.sample(article_ids, 2 * size)
    chosen = [rng.choice(sorted(by_article[a], key=lambda s: s.set_id)).set_id for a in picked]
    return {
        "dev": SplitSpec("dev", source, chosen[:size]),
        "confirm": SplitSpec("confirm", source, chosen[size:]),
    }

# raptor/eval/splits.py › def load_splits(path: str | Path = DEFAULT_SPLITS_FILE) -> dict[str, SplitSpec]
# uses: from pathlib import Path; import yaml
def load_splits(path: str | Path = DEFAULT_SPLITS_FILE) -> dict[str, SplitSpec]:
    doc = yaml.safe_load(Path(path).read_text(encoding="utf-8"))
    return {
        name: SplitSpec(name, spec.get("source", "dev"), list(spec["set_ids"]))
        for name, spec in doc["splits"].items()
    }

