# raptor/models/cache.py › class DiskCache
class DiskCache:
    """A small SQLite key/value store (safe to share across threads)."""

# raptor/models/cache.py › class DiskCache › def key(*parts: Any) -> str
# uses: import hashlib; import json; from typing import Any
    @staticmethod
    def key(*parts: Any) -> str:
        blob = json.dumps(parts, sort_keys=True, ensure_ascii=False, default=str).encode()
        return hashlib.sha256(blob).hexdigest()

# raptor/models/cache.py › class DiskCache › def get(self, key: str) -> bytes | None
    def get(self, key: str) -> bytes | None:
        with self._lock:
            row = self._conn.execute("SELECT v FROM kv WHERE k = ?", (key,)).fetchone()
        return None if row is None else bytes(row[0])

# raptor/models/cache.py › class DiskCache › def get_many(self, keys: Sequence[str]) -> dict[str, bytes]
# uses: from collections.abc import Iterator, Sequence
    def get_many(self, keys: Sequence[str]) -> dict[str, bytes]:
        out: dict[str, bytes] = {}
        with self._lock:
            for i in range(0, len(keys), 500):
                chunk = list(keys[i : i + 500])
                q = "SELECT k, v FROM kv WHERE k IN ({})".format(",".join("?" * len(chunk)))
                for k, v in self._conn.execute(q, chunk):
                    out[k] = bytes(v)
        return out

# raptor/models/cache.py › class DiskCache › DiskCache.set, DiskCache.close
    def set(self, key: str, value: bytes) -> None:
        self.set_many({key: value})

    def close(self) -> None:
        with self._lock:
            self._conn.close()

# raptor/models/cache.py › class CachedEmbeddingModel(BaseEmbeddingModel)
# uses: from .base import BaseEmbeddingModel, BaseQAModel, BaseSummarizationModel
class CachedEmbeddingModel(BaseEmbeddingModel):

# raptor/models/cache.py › class CachedEmbeddingModel › def _lookup(self, kind: str, texts: Sequence[str], compute) -> np.ndarray
# uses: from collections.abc import Iterator, Sequence; import numpy as np
    def _lookup(self, kind: str, texts: Sequence[str], compute) -> np.ndarray:
        keys = [DiskCache.key("emb", self.inner.model_id, kind, t) for t in texts]
        found = self.cache.get_many(list(dict.fromkeys(keys)))
        missing: dict[str, int] = {}  # unique missing key -> first position
        for i, k in enumerate(keys):
            if k not in found and k not in missing:
                missing[k] = i
        self.stats.misses += len(missing)
        self.stats.hits += len(texts) - len(missing)
        if missing:
            computed = np.asarray(compute([texts[i] for i in missing.values()]), dtype=np.float32)
            new = {k: computed[j].tobytes() for j, k in enumerate(missing)}
            self.cache.set_many(new)
            found.update(new)
        return np.stack([np.frombuffer(found[k], dtype=np.float32) for k in keys])

# raptor/models/cache.py › class CachedEmbeddingModel › def embed_documents(self, texts: Sequence[str]) -> np.ndarray
# uses: from collections.abc import Iterator, Sequence; import numpy as np
    def embed_documents(self, texts: Sequence[str]) -> np.ndarray:
        if not texts:
            return np.zeros((0, 0), dtype=np.float32)
        return self._lookup("doc", texts, self.inner.embed_documents)

