    def generate_json(
        self, prompt: str, schema: dict[str, Any], *, temperature: float = 0.0
    ) -> str | None:
        """Generate a JSON reply that follows ``schema``. Returns the raw text (``None`` if filtered)."""
        resp = self._generate(
