# raptor/models/gemini.py › class GeminiQAModel › def answer_question(self, context: str, question: str) -> str
    def answer_question(self, context: str, question: str) -> str:
        resp = self._generate(
            self.prompt_template.format(context=context, question=question),
            temperature=self.temperature,
        )
        return (
            self._text(resp)
            or "The model returned no answer (the response may have been filtered)."
        )

# raptor/models/gemini.py › class GeminiQAModel › def stream_answer(self, context: str, question: str) -> Iterator[str]
# uses: from collections.abc import Iterator, Sequence; from typing import Any
    def stream_answer(self, context: str, question: str) -> Iterator[str]:
        from google.genai import types

        prompt = self.prompt_template.format(context=context, question=question)
        cfg = types.GenerateContentConfig(
            temperature=self.temperature, safety_settings=_safety_settings()
        )

        def start(client: Any):
            # Errors surface on the first chunk, so pull it inside the retried call.
            it = iter(
                client.models.generate_content_stream(
                    model=self.model_name, contents=prompt, config=cfg
                )
            )
            return next(it, None), it

        first, rest = self._pool.call(self._bucket, self._rpm, start)
        for chunk in _chain(first, rest):
            if self._text(chunk):
                yield chunk.text

# raptor/models/gemini.py › _chain, hash_text
# uses: from collections.abc import Iterator, Sequence; from typing import Any
def _chain(first: Any, rest: Iterator[Any]) -> Iterator[Any]:
    if first is not None:
        yield first
    yield from rest

def hash_text(text: str) -> str:
    import hashlib

    return hashlib.sha256(text.encode()).hexdigest()[:8]

# raptor/models/keypool.py › class QuotaExhaustedError(RuntimeError)
class QuotaExhaustedError(RuntimeError):
    """Every configured key has used up its daily quota for a model."""

# raptor/models/keypool.py › def is_retryable(exc: BaseException) -> bool
def is_retryable(exc: BaseException) -> bool:
    if is_rate_limit(exc):
        return True
    code = getattr(exc, "code", None)
    if isinstance(code, int) and code >= 500:
        return True
    text = str(exc).lower()
    return "unavailable" in text or "deadline" in text or "timed out" in text

# raptor/models/keypool.py › class KeyPool › def __len__(self) -> int
    def __len__(self) -> int:
        return len(self.slots)

# raptor/models/keypool.py › class KeyPool › def _all_daily_exhausted(self, bucket: str) -> bool
# uses: import time
    def _all_daily_exhausted(self, bucket: str) -> bool:
        now = time.monotonic()
        with self._lock:
            return all(
                s.disabled or s.cooldown_until.get(bucket, 0.0) - now > RATE_LIMIT_COOLDOWN
                for s in self.slots
            )

# raptor/models/keypool.py › class KeyPool › def call(self, bucket: str, rpm: int | None, fn: Callable[[Any], T], *, cost: int = 1) -> T (part 1/2)
# uses: from collections.abc import Callable, Sequence; from typing import Any, TypeVar
    def call(self, bucket: str, rpm: int | None, fn: Callable[[Any], T], *, cost: int = 1) -> T:
        """Run ``fn(client)`` on an available key, failing over and retrying as needed.

        ``cost`` is how many requests the call counts as against ``rpm`` (Gemini's free
        tier counts every text in a batch embedding call as one request).
        """
        attempts = MAX_ATTEMPTS + len(self.slots)
        for attempt in range(attempts):
            slot = self.acquire(bucket, rpm, cost)
            try:
                return fn(slot.client)
            except Exception as exc:
                if is_auth_error(exc) and any(not s.disabled for s in self.slots if s is not slot):
                    logger.warning(
                        "Gemini key #%d was rejected (%s); disabling it for this process",
                        slot.index + 1,
                        str(exc)[:80],
                    )
                    with self._lock:
                        slot.disabled = True
                    continue
                if not is_retryable(exc) or attempt == attempts - 1:
                    raise
                if is_rate_limit(exc):
                    seconds = _cooldown_for(exc)
                    logger.warning(
                        "Gemini key #%d rate-limited on %s; cooling down %.0fs%s",
                        slot.index + 1,
                        bucket,
                        seconds,
                        " (trying next key)" if len(self.slots) > 1 else "",
                    )
                    self.cooldown(slot, bucket, seconds)
                    if FAIL_ON_DAILY_QUOTA and self._all_daily_exhausted(bucket):
                        raise QuotaExhaustedError(
                            f"daily quota used up on every key for {bucket}"
                        ) from exc
                else:

# raptor/models/local.py › def resolve_local_embedding(name: str) -> tuple[str, str, str]
def resolve_local_embedding(name: str) -> tuple[str, str, str]:
    """Map a model name or alias to ``(hub id, query prefix, document prefix)``."""
    if name in LOCAL_EMBEDDINGS:
        return LOCAL_EMBEDDINGS[name]
    for hub_id, q, d in LOCAL_EMBEDDINGS.values():
        if name == hub_id:
            return hub_id, q, d
    return name, "", ""

