# uses: from collections.abc import Callable; from typing import Any, Generic, TypeVar
class Registry(Generic[T]):

    def __init__(self, kind: str) -> None:
        self.kind = kind
        self._items: dict[str, Callable[..., T]] = {}

# raptor/registry.py › class Registry › def register(self, name: str) -> Callable[[Callable[..., T]], Callable[..., T]]
# uses: from collections.abc import Callable
    def register(self, name: str) -> Callable[[Callable[..., T]], Callable[..., T]]:
        def deco(factory: Callable[..., T]) -> Callable[..., T]:
            if name in self._items:
                raise ValueError(f"{self.kind} '{name}' is already registered")
            self._items[name] = factory
            return factory

        return deco

# raptor/registry.py › class Registry › def create(self, name: str, **kwargs: Any) -> T
# uses: from typing import Any, Generic, TypeVar
    def create(self, name: str, **kwargs: Any) -> T:
        try:
            factory = self._items[name]
        except KeyError:
            raise ValueError(
                f"unknown {self.kind} '{name}'. Available: {sorted(self._items)}"
            ) from None
        return factory(**kwargs)

# raptor/registry.py › class Registry › Registry.names, Registry.__contains__
    def names(self) -> list[str]:
        return sorted(self._items)

    def __contains__(self, name: object) -> bool:
        return name in self._items

