                    out.put(("error", {"side": name, "message": f"{type(exc).__name__}: {exc}"}))
                finally:
                    out.put(None)

            threads = [
                threading.Thread(target=side, args=(n,), daemon=True) for n in ("flat", "raptor")
            ]
            for t in threads:
                t.start()
            remaining = len(threads)
            while remaining:
                item = out.get()
                if item is None:
                    remaining -= 1
                else:
                    yield item
            yield "done", {}

        return sse_response(events())

