# uses: from pathlib import Path; from fastapi import APIRouter, FastAPI, File, Form, Header, HTTPException, Query, UploadFile; from fastapi.responses import FileResponse, JSONResponse; from fastapi.staticfiles import StaticFiles
def _mount_frontend(app: FastAPI, dist: Path) -> None:
    index = dist / "index.html"
    if not index.is_file():

        @app.get("/", include_in_schema=False)
        def no_frontend() -> JSONResponse:
            return JSONResponse(
                {
                    "message": "The web UI is not built. Run `npm install && npm run build` in web/, "
                    "or use `npm run dev` there. The API is at /api and its docs at /docs."
                }
            )

        return
    if (dist / "assets").is_dir():
        app.mount("/assets", StaticFiles(directory=dist / "assets"), name="assets")

    @app.get("/{path:path}", include_in_schema=False)
    def spa(path: str) -> FileResponse:
        if path.startswith("api/"):
            raise HTTPException(404, "not found")
        candidate = (dist / path).resolve()
        if path and candidate.is_file() and dist.resolve() in candidate.parents:
            return FileResponse(candidate)
        return FileResponse(index)

