        self.inner = inner
        self.tracker = tracker

# raptor/server/builds.py › class _TrackingChunker › def split(self, text: str) -> list[Chunk]
# uses: from ..chunking import Chunk, Chunker, default_tokenizer, make_chunker; from .indexes import preview
    def split(self, text: str) -> list[Chunk]:
        chunks = self.inner.split(text)
        t = self.tracker
        with t.lock:
            t.texts = {i: c.text for i, c in enumerate(chunks)}
            t.layer_start, t.layer_count, t.layer = 0, len(chunks), 0
        t.job.emit(
            "chunks",
            {
                "count": len(chunks),
                "chars": len(text),
                "chunks": [
                    {
                        "id": i,
                        "preview": preview(c.text, 90),
                        "tokens": len(t.tokenizer.encode(c.text, disallowed_special=())),
                    }
                    for i, c in enumerate(chunks)
                ],
            },
        )
        return chunks

