# raptor/server/fakes.py › class FakeEmbeddingModel › def embed_documents(self, texts: Sequence[str]) -> np.ndarray
# uses: from collections.abc import Iterator, Sequence; import numpy as np
    def embed_documents(self, texts: Sequence[str]) -> np.ndarray:
        if not texts:
            return np.zeros((0, FAKE_DIM), dtype=np.float32)
        return np.stack([self._vector(t) for t in texts])

# raptor/server/fakes.py › class FakeSummarizationModel › def __init__(self, delay: float = 0.0) -> None
    def __init__(self, delay: float = 0.0) -> None:
        self.delay = delay

# raptor/server/fakes.py › class FakeSummarizationModel › def summarize(self, context: str, max_tokens: int = 150) -> str
# uses: import time
    def summarize(self, context: str, max_tokens: int = 150) -> str:
        if self.delay:
            time.sleep(self.delay)
        sentences = [s.strip() for s in _SENTENCE.split(" ".join(context.split())) if s.strip()]
        if not sentences:
            return context[:200]
        freq: dict[str, int] = {}
        for w in _words(context):
            freq[w] = freq.get(w, 0) + 1

        def score(s: str) -> float:
            ws = _words(s)
            return sum(freq.get(w, 0) for w in ws) / (len(ws) + 3)

        ranked = sorted(range(len(sentences)), key=lambda i: (-score(sentences[i]), i))
        picked: list[int] = []
        budget = max(12, int(max_tokens * 0.75))
        used = 0
        for i in ranked:
            n = len(sentences[i].split())
            if picked and used + n > budget:
                continue
            picked.append(i)
            used += n
            if used >= budget:
                break
        text = " ".join(sentences[i] for i in sorted(picked))
        words = text.split()
        return " ".join(words[:budget]) + ("…" if len(words) > budget else "")

# raptor/server/fakes.py › class FakeQAModel › FakeQAModel.__init__, FakeQAModel.answer_question
    def __init__(self, delay: float = 0.0) -> None:
        self.delay = delay

    def answer_question(self, context: str, question: str) -> str:
        return "".join(self._compose(context, question))

# raptor/server/fakes.py › class FakeQAModel › def stream_answer(self, context: str, question: str) -> Iterator[str]
# uses: import time; from collections.abc import Iterator, Sequence
    def stream_answer(self, context: str, question: str) -> Iterator[str]:
        for piece in self._compose(context, question):
            if self.delay:
                time.sleep(self.delay)
            yield piece

# raptor/server/fakes.py › class FakeQAModel › def _best_sentences(context: str, question: str, n: int) -> list[str]
    @staticmethod
    def _best_sentences(context: str, question: str, n: int) -> list[str]:
        q = set(_words(question))
        sentences = [s.strip() for s in _SENTENCE.split(" ".join(context.split())) if s.strip()]
        scored = sorted(
            ((len(q & set(_words(s))), -i, s) for i, s in enumerate(sentences)), reverse=True
        )
        out = [s for score, _, s in scored[:n] if score > 0]
        return [s if len(s) < 280 else s[:277] + "…" for s in out]

