# raptor/server/runs.py › def mcnemar_exact(fixed: int, broken: int) -> float
# uses: import math
def mcnemar_exact(fixed: int, broken: int) -> float:
    """Two-sided exact McNemar test (binomial on the discordant pairs)."""
    n = fixed + broken
    if n == 0:
        return 1.0
    k = min(fixed, broken)
    tail = sum(math.comb(n, i) for i in range(k + 1)) / 2**n
    return min(1.0, 2 * tail)

# raptor/server/sse.py › def sse_response(events: Iterable[Event | str]) -> StreamingResponse
# uses: from collections.abc import Iterable, Iterator; from fastapi.responses import StreamingResponse
def sse_response(events: Iterable[Event | str]) -> StreamingResponse:
    """Stream ``(event, data)`` tuples (or preformatted strings) as ``text/event-stream``."""

    def body() -> Iterator[str]:
        try:
            for item in events:
                yield item if isinstance(item, str) else format_event(*item)
        except Exception as exc:  # surface failures to the client instead of a broken stream
            yield format_event("error", {"message": f"{type(exc).__name__}: {exc}"})

    return StreamingResponse(
        body(),
        media_type="text/event-stream",
        headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
    )

