# uses: import pickle
class _RestrictedUnpickler(pickle.Unpickler):

# raptor/storage.py › class _RestrictedUnpickler › def find_class(self, module: str, name: str) -> Any
# uses: import pickle; from typing import Any
    def find_class(self, module: str, name: str) -> Any:
        if (module, name) in _ALLOWED_GLOBALS:
            return _ALLOWED_GLOBALS[(module, name)]
        if module in ("numpy", "numpy.core.multiarray", "numpy._core.multiarray") and name in (
            "ndarray",
            "dtype",
            "_reconstruct",
            "scalar",
        ):
            return super().find_class(module, name)
        raise pickle.UnpicklingError(f"refusing to load global {module}.{name} from legacy tree")

# raptor/storage.py › def load_legacy_pickle(path: str | Path) -> Tree (part 1/2)
# uses: from pathlib import Path; import numpy as np; from .types import Node, Tree
def load_legacy_pickle(path: str | Path) -> Tree:
    """Import a tree pickled by the original RAPTOR (``RetrievalAugmentation.save``)."""
    with open(path, "rb") as fh:
        obj = _RestrictedUnpickler(fh).load()
    if not isinstance(obj, _LegacyTree):
        raise ValueError(f"{path} does not contain a legacy RAPTOR Tree")
    legacy = obj.__dict__

    index_to_layer: dict[int, int] = {}
    for layer, nodes in legacy["layer_to_nodes"].items():
        for n in nodes:
            index_to_layer[n.__dict__["index"]] = int(layer)

    def convert(ln: _LegacyNode) -> Node:
        d = ln.__dict__
        return Node(
            text=d["text"],
            index=d["index"],
            children=set(d["children"]),
            embeddings={k: np.asarray(v, dtype=np.float32) for k, v in d["embeddings"].items()},
            layer=index_to_layer.get(d["index"], 0),
        )

    all_nodes = {i: convert(n) for i, n in legacy["all_nodes"].items()}
    layer_to_nodes = {
        int(layer): [all_nodes[n.__dict__["index"]] for n in nodes]
        for layer, nodes in legacy["layer_to_nodes"].items()
    }
    keys = {k for n in all_nodes.values() for k in n.embeddings}
    tree = Tree(
        all_nodes=all_nodes,
        root_nodes={i: all_nodes[i] for i in legacy["root_nodes"]},
        leaf_nodes={i: all_nodes[i] for i in legacy["leaf_nodes"]},
        num_layers=int(legacy["num_layers"]),

# raptor/storage.py › def load_legacy_pickle(path: str | Path) -> Tree (part 2/2)
# uses: import pickle
        layer_to_nodes=layer_to_nodes,
        metadata={
            "embedding_key": sorted(keys)[0] if len(keys) == 1 else "EMB",
            "source": "legacy-pickle",
        },
    )
    tree.validate()
    return tree

# raptor/types.py › class Node › def is_leaf(self) -> bool
    @property
    def is_leaf(self) -> bool:
        return not self.children

# raptor/types.py › class Tree › Tree.embedding_key, Tree.node_layer
    @property
    def embedding_key(self) -> str:
        return str(self.metadata.get("embedding_key", DEFAULT_EMBEDDING_KEY))

    def node_layer(self, index: int) -> int:
        return self.all_nodes[index].layer

# raptor/types.py › class Tree › Tree.parents_of, Tree.nodes_in_layer
    def parents_of(self, index: int) -> list[int]:
        return [n.index for n in self.all_nodes.values() if index in n.children]

    def nodes_in_layer(self, layer: int) -> list[Node]:
        return list(self.layer_to_nodes.get(layer, []))

# raptor/types.py › class Tree › def invalidate_cache(self) -> None
    def invalidate_cache(self) -> None:
        self._matrix_cache.clear()

# raptor/types.py › class Tree › def validate(self) -> None
    def validate(self) -> None:
        """Raise ``ValueError`` if the tree is internally inconsistent."""
        for idx, node in self.all_nodes.items():
            if idx != node.index:
                raise ValueError(f"node key {idx} != node.index {node.index}")
            missing = node.children - self.all_nodes.keys()
            if missing:
                raise ValueError(f"node {idx} has unknown children {sorted(missing)}")
        for layer, nodes in self.layer_to_nodes.items():
            for n in nodes:
                if n.layer != layer:
                    raise ValueError(f"node {n.index} in layer list {layer} has layer {n.layer}")

# raptor/types.py › class Tree › def from_layers(cls, layer_to_nodes: dict[int, list[Node]], metadata: dict[str, Any] | None = None,) -> Tree
# uses: from typing import Any
    @classmethod
    def from_layers(
        cls,
        layer_to_nodes: dict[int, list[Node]],
        metadata: dict[str, Any] | None = None,
    ) -> Tree:
        all_nodes = {n.index: n for nodes in layer_to_nodes.values() for n in nodes}
        top = max(layer_to_nodes) if layer_to_nodes else 0
        return cls(
            all_nodes=all_nodes,
            root_nodes={n.index: n for n in layer_to_nodes.get(top, [])},
            leaf_nodes={n.index: n for n in layer_to_nodes.get(0, [])},
            num_layers=top,
            layer_to_nodes=layer_to_nodes,
            metadata=dict(metadata or {}),
        )

# raptor/types.py › def nodes_text(nodes: Iterable[Node]) -> str
# uses: from collections.abc import Iterable
def nodes_text(nodes: Iterable[Node]) -> str:
    """Join node texts the way the original RAPTOR did (one paragraph per node)."""
    return "".join(" ".join(n.text.splitlines()) + "\n\n" for n in nodes)

