# tests/conftest.py › class HashEmbedder › def vector(text: str) -> np.ndarray
# uses: import hashlib; import numpy as np
    @staticmethod
    def vector(text: str) -> np.ndarray:
        v = np.zeros(DIM, dtype=np.float32)
        for w in _WORD.findall(text.lower()):
            v[int(hashlib.md5(w.encode()).hexdigest(), 16) % DIM] += 1.0
        n = np.linalg.norm(v)
        return v / n if n else v + 1e-3

# tests/conftest.py › class HashEmbedder › def embed_documents(self, texts: Sequence[str]) -> np.ndarray
# uses: from collections.abc import Sequence; import numpy as np
    def embed_documents(self, texts: Sequence[str]) -> np.ndarray:
        self.doc_calls += 1
        self.texts_embedded += len(texts)
        return (
            np.stack([self.vector(t) for t in texts]) if texts else np.zeros((0, DIM), np.float32)
        )

# tests/conftest.py › class EchoSummarizer › def summarize(self, context: str, max_tokens: int = 150) -> str
    def summarize(self, context: str, max_tokens: int = 150) -> str:
        self.calls += 1
        firsts = [p.split(". ")[0].strip() for p in context.split("\n\n") if p.strip()]
        words = " ".join(firsts).split()
        return " ".join(words[:max_tokens])

