# uses: import numpy as np; from raptor import FlatRAG, Node, RetrievalConfig, Tree, TreeRetriever, load_legacy_pickle
def toy_tree() -> Tree:
    def node(i, vec, layer=0, children=(), text=None):
        return Node(
            text or f"node {i}", i, set(children), {"EMB": np.asarray(vec, np.float32)}, layer
        )

    leaves = [node(0, [1, 0, 0]), node(1, [0.9, 0.1, 0]), node(2, [0, 1, 0]), node(3, [0, 0, 1])]
    tops = [node(4, [1, 0.05, 0], 1, (0, 1)), node(5, [0, 0.7, 0.7], 1, (2, 3))]
    return Tree.from_layers({0: leaves, 1: tops})

# tests/test_server.py › def sse(text: str) -> list[tuple[str, dict]]
# uses: import json
def sse(text: str) -> list[tuple[str, dict]]:
    events = []
    for block in text.split("\n\n"):
        name, data = None, []
        for line in block.splitlines():
            if line.startswith("event:"):
                name = line[6:].strip()
            elif line.startswith("data:"):
                data.append(line[5:].strip())
        if name:
            events.append((name, json.loads("\n".join(data) or "null")))
    return events

